function commerceDeliveryPage(){
 const body='<main class="wrap"><section class="page"><h1>Teslimat</h1><p>İlçe, minimum sipariş, teslimat ücreti ve soğuk zincir kuralları teklif/sipariş aşamasında doğrulanır.</p><div id="deliveryList" class="helpgrid"><div class="help"><b>Teslimat kuralları yükleniyor…</b></div></div><p><a class="btn" style="background:#0768b2;color:#fff" href="/iletisim">Teslimat Hakkında Sor</a></p></section></main>';
 const script="fetch('/api/storefront-v2',{headers:{accept:'application/json'},cache:'no-store'}).then(r=>r.json()).then(j=>{const a=Array.isArray(j.delivery)?j.delivery:[];deliveryList.innerHTML=a.length?a.map(x=>{const title=[x.region,x.district].filter(Boolean).join(' • '),parts=[];if(Number(x.min_order)>0)parts.push('Minimum sipariş: '+Number(x.min_order).toLocaleString('tr-TR')+' ₺');if(Number(x.fee)>0)parts.push('Teslimat: '+Number(x.fee).toLocaleString('tr-TR')+' ₺');if(Number(x.free_threshold)>0)parts.push('Ücretsiz limit: '+Number(x.free_threshold).toLocaleString('tr-TR')+' ₺');if(x.delivery_days)parts.push(String(x.delivery_days));if(Number(x.cold_chain)!==0)parts.push('Soğuk zincir');return '<article class=\\\"help\\\"><b>'+String(title||'Teslimat').replace(/[&<>]/g,'')+'</b><span>'+parts.join(' • ').replace(/[&<>]/g,'')+'</span></article>'}).join(''):'<div class=\\\"help\\\"><b>Teslimat bilgisi</b><span>İlçe bazlı kurallar yönetim panelinden yayınlandığında burada görünür.</span></div>'}).catch(()=>deliveryList.innerHTML='<div class=\\\"help\\\">Teslimat bilgileri yüklenemedi.</div>')";
 return html(commerceClientShell('Teslimat | Okyanus EDT',body,script));
}

export async function commerceRoute(request,env){
 const u=new URL(request.url),p=u.pathname.length>1&&u.pathname.endsWith("/")?u.pathname.slice(0,-1):u.pathname,m=request.method;
 if(!["GET","HEAD"].includes(m)&&p!=="/api/storefront-v2")return null;
 if((m==="GET"||m==="HEAD")&&p==="/")return html(home());
 if((m==="GET"||m==="HEAD")&&(p==="/yardim"||p==="/site-yardim"))return html(help());
 if((m==="GET"||m==="HEAD")&&p==="/iletisim")return html(contact());
 if((m==="GET"||m==="HEAD")&&p==="/icerik-studyo")return html(studio());
 if((m==="GET"||m==="HEAD")&&p==="/urunler")return commerceCatalogPage();
 if((m==="GET"||m==="HEAD")&&p==="/sepet")return commerceCartPage();
 if((m==="GET"||m==="HEAD")&&p.startsWith("/urun/"))return commerceProductPage(decodeURIComponent(p.slice(6)));
 if((m==="GET"||m==="HEAD")&&p==="/markalar")return commerceBrandsPage();
 if((m==="GET"||m==="HEAD")&&p==="/kampanyalar")return commerceCampaignsPage();
 if((m==="GET"||m==="HEAD")&&p==="/teslimat")return commerceDeliveryPage();
 if(m==="GET"&&p==="/api/storefront-v2")return storefront(env);
 return null;
}

export const OKY_COMMERCE_V2_BUILD=BUILD;
